function fold(key,title,ico,sub,children){const d=document.createElement('details');d.className='fw-fold';d.dataset.fold=key;d.open=openState.has(key);const sm=document.createElement('summary');sm.innerHTML='<span class="fw-fold-icon" aria-hidden="true">'+ico+'</span><span>'+title+'<small>'+sub+'</small></span>';const body=document.createElement('div');body.className='fw-fold-body';body.append(...children);d.append(sm,body);d.addEventListener('toggle',()=>{if(!d.isConnected)return;if(d.open)openState.add(key);else openState.delete(key)});return d}
function resetPicker(){pickerOpen=false;query='';category='';chosen='';portion='1';custom='';customK='';customP=''}
