 if(selected===dateKey(new Date())){const wb=document.createElement('button');wb.textContent='歩行タイマーを開く';wb.onclick=()=>{if($('walkLaunch'))$('walkLaunch').click()};ws.append(document.createElement('br'),wb)}
 const total=sums(l);meal.innerHTML='<h2>食事を記録</h2><p class="muted">食事区分を選んで、＋で食品を1品ずつ追加してください。料理・外食は標準量の概算。成分表の食品は可食部100gが基準です。<br><small>成分表の出典：<a href="https://www.mext.go.jp/a_menu/syokuhinseibun/mext_00001.html" target="_blank" rel="noopener">文部科学省 日本食品標準成分表（八訂）増補2023年</a>（<a href="https://github.com/Yocchan1513/omame-nutrition-api/blob/main/app/data/food_composition_seed.csv" target="_blank" rel="noopener">公開CSV加工版</a>を抽出・再分類）。</small></p><div class="fw-meals">'+mealNames.map((n,i)=>'<button type="button" data-meal-choice="'+i+'" class="'+(i===mealIndex?'active':'')+'" aria-pressed="'+(i===mealIndex)+'">'+n+'<small>'+l.foods.filter(f=>f.meal===i).length+'品</small></button>').join('')+'</div><div class="fw-meal-heading"><h3>'+mealNames[mealIndex]+'</h3></div><div>'+foodList(l)+'</div><div class="fw-meal-total" id="fwMealTotal"></div><button class="fw-add-plus" id="fwPlus"><b>＋</b> 食品を追加</button><div class="line"></div><div id="foodTotal">'+totalText(total,l)+'</div>';
 const a=fold('strength','筋トレ','◆',actualSets(l)?actualSets(l)+'セット記録済み':'未入力',[training]);const b=fold('food','食事・間食','◉',l.foods.length?l.foods.length+'品 · P '+Math.round(total.p)+'g'+(total.pu?'＋不明分':''):'未入力',[meal]);const c=fold('recovery','歩行・睡眠・回復','◷',l.walk===''?'歩行未入力':'歩行 '+l.walk+'分',[rec]);root.replaceChildren(h,a,b,c,meta);
 for(const button of meal.querySelectorAll('[data-meal-choice]'))button.onclick=()=>{mealIndex=+button.dataset.mealChoice;resetPicker();render()};$('fwPlus').onclick=()=>{pickerOpen=!pickerOpen;if(!pickerOpen)resetPicker();render();if(pickerOpen)$('fwPicker').scrollIntoView({block:'nearest'})};
